sed -i '/const \[deleteDialog/a \  const [detailsModalCustomer, setDetailsModalCustomer] = useState<User | null>(null);\n\n  const handleExportCSV = () => {\n    const headers = ["ID", "Firma", "Yetkili", "E-posta", "Rol", "Durum"];\n    const rows = filteredCustomers.map(c => [\n      c.id,\n      c.companyName || "-",\n      c.name,\n      c.email,\n      c.role,\n      c.status === "suspended" ? "Askida" : "Aktif"\n    ]);\n    const csvContent = [\n      headers.join(","),\n      ...rows.map(r => r.map(cell => `"${cell}"`).join(","))\n    ].join("\\n");\n    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });\n    const link = document.createElement("a");\n    link.href = URL.createObjectURL(blob);\n    link.download = `musteriler_${new Date().toISOString().split("T")[0]}.csv`;\n    link.click();\n  };' src/components/CustomerManagement.tsx
